function work_management_require_note(string$note,string$message='Governance evidence is required.'):string{$note=trim($note);if($note==='')throw new RuntimeException($message);return mb_substr($note,0,5000);}
function work_management_assert_item_action(array$item,string$capability='execute'):array
{
    work_management_require($capability);if(!work_management_find_item((int)$item['id']))throw new RuntimeException('Work item not found or outside the active company scope.');$user=current_user();if(!$user)throw new RuntimeException('Authentication is required.');if(!work_management_user_can_receive($user,(int)$item['entity_id'],(string)$item['required_permission']))throw new RuntimeException('The work item requires a permission or company scope you do not hold.');return$user;
