function work_management_transition(array$item,string$toStatus,string$eventType,string$note,array$metadata=[]):array
{
    $allowed=['open'=>['in_progress','blocked','cancelled'],'in_progress'=>['blocked','waiting_review','completed','cancelled'],'blocked'=>['in_progress','waiting_review','cancelled'],'waiting_review'=>['waiting_approval','in_progress','completed','blocked'],'waiting_approval'=>['completed','in_progress','blocked'],'completed'=>[],'cancelled'=>[]];$from=(string)$item['status'];if(!in_array($toStatus,$allowed[$from]??[],true))throw new RuntimeException('The work item cannot move from '.status_label($from).' to '.status_label($toStatus).'.');$note=work_management_require_note($note);$item['status']=$toStatus;$item['last_activity_at']=date('Y-m-d H:i:s');if($toStatus==='in_progress'&&empty($item['started_at']))$item['started_at']=date('Y-m-d H:i:s');if($toStatus==='completed'){$item['completed_at']=date('Y-m-d H:i:s');$item['completed_by']=(int)current_user()['id'];}$item=work_management_save_item($item);work_management_add_event((int)$item['id'],$eventType,$from,$toStatus,(string)$item['priority'],$note,$metadata);return$item;
