}
function work_management_start_item(int$itemId,string$note):array{$item=work_management_find_item($itemId);if(!$item)throw new RuntimeException('Work item not found.');work_management_assert_item_action($item,'execute');if(!work_management_item_can_act($item))throw new RuntimeException('Only the assigned owner or role may start this work item.');if($item['status']!=='open')throw new RuntimeException('Only open work can start.');return work_management_transition($item,'in_progress','work_started',$note);}
function work_management_block_item(int$itemId,string$note):array{$item=work_management_find_item($itemId);if(!$item)throw new RuntimeException('Work item not found.');work_management_assert_item_action($item,'execute');if(!work_management_item_can_act($item))throw new RuntimeException('Only the assigned owner or administrator may block this work.');if(!in_array((string)$item['status'],['open','in_progress','waiting_review','waiting_approval'],true))throw new RuntimeException('This work item cannot be blocked from its current state.');return work_management_transition($item,'blocked','work_blocked',$note);}
function work_management_resume_item(int$itemId,string$note):array{$item=work_management_find_item($itemId);if(!$item)throw new RuntimeException('Work item not found.');work_management_assert_item_action($item,'execute');if(!work_management_item_can_act($item))throw new RuntimeException('Only the assigned owner or administrator may resume this work.');if($item['status']!=='blocked')throw new RuntimeException('Only blocked work can resume.');return work_management_transition($item,'in_progress','work_resumed',$note);}
function work_management_submit_review(int$itemId,string$note):array
{
    $item=work_management_find_item($itemId);if(!$item)throw new RuntimeException('Work item not found.');$user=work_management_assert_item_action($item,'execute');if(!work_management_item_can_act($item,$user))throw new RuntimeException('Only the assigned execution owner may submit work for review.');if(in_array((int)$user['id'],array_filter([(int)($item['reviewer_id']??0),(int)($item['approver_id']??0)]),true))throw new RuntimeException('Execution ownership must remain separate from review and approval.');if(empty($item['reviewer_id'])&&empty($item['approver_id']))throw new RuntimeException('This work item has no independent review or approval assignment.');if(!in_array((string)$item['status'],['in_progress','blocked'],true))throw new RuntimeException('Only active work can be submitted for review.');return work_management_transition($item,'waiting_review','work_submitted_for_review',$note);
