function work_management_review_item(int$itemId,string$note):array
{
    $item=work_management_find_item($itemId);if(!$item)throw new RuntimeException('Work item not found.');$user=work_management_assert_item_action($item,'review');if($item['status']!=='waiting_review')throw new RuntimeException('The work item is not awaiting review.');if((int)($item['reviewer_id']??0)!==(int)$user['id'])throw new RuntimeException('Only the assigned independent reviewer may review this work item.');if(in_array((int)$user['id'],[(int)($item['assigned_user_id']??0),(int)($item['created_by']??0)],true))throw new RuntimeException('The execution owner or creator cannot independently review the same work item.');return!empty($item['approver_id'])?work_management_transition($item,'waiting_approval','work_reviewed',$note,['reviewed_by'=>(int)$user['id']]):work_management_transition($item,'completed','work_reviewed_and_completed',$note,['reviewed_by'=>(int)$user['id']]);
