function work_management_approve_item(int$itemId,string$note):array
{
    $item=work_management_find_item($itemId);if(!$item)throw new RuntimeException('Work item not found.');$user=work_management_assert_item_action($item,'approve');if($item['status']!=='waiting_approval')throw new RuntimeException('The work item is not awaiting approval.');if((int)($item['approver_id']??0)!==(int)$user['id'])throw new RuntimeException('Only the assigned approver may approve this work item.');if(in_array((int)$user['id'],[(int)($item['assigned_user_id']??0),(int)($item['reviewer_id']??0),(int)($item['created_by']??0)],true))throw new RuntimeException('Approval must remain separate from creation, execution, and review.');return work_management_transition($item,'completed','work_approved_and_completed',$note,['approved_by'=>(int)$user['id']]);
}
function work_management_complete_item(int$itemId,string$note):array
{
    $item=work_management_find_item($itemId);if(!$item)throw new RuntimeException('Work item not found.');work_management_assert_item_action($item,'execute');if(!work_management_item_can_act($item))throw new RuntimeException('Only the assigned owner may complete this work item.');if(!empty($item['evidence_required']))$note=work_management_require_note($note,'Completion evidence is required.');if(!empty($item['reviewer_id'])||!empty($item['approver_id']))throw new RuntimeException('Submit this work item for independent review instead of completing it directly.');if($item['status']!=='in_progress')throw new RuntimeException('Only in-progress work can complete.');return work_management_transition($item,'completed','work_completed',$note);
