function work_management_reassign_item(int$itemId,int$targetUserId,string$note):array
{
    work_management_require('assign');$item=work_management_find_item($itemId);if(!$item)throw new RuntimeException('Work item not found.');$target=work_management_active_user($targetUserId);if(!$target||!work_management_user_can_receive($target,(int)$item['entity_id'],(string)$item['required_permission']))throw new RuntimeException('The selected assignee is outside the permitted company or permission scope.');if(in_array($targetUserId,array_filter([(int)($item['reviewer_id']??0),(int)($item['approver_id']??0)]),true))throw new RuntimeException('The execution assignee cannot also be the reviewer or approver.');$before=(int)($item['assigned_user_id']??0);$item['assigned_user_id']=$targetUserId;$item['claimed_at']=null;$item['last_activity_at']=date('Y-m-d H:i:s');$item=work_management_save_item($item);work_management_add_event($itemId,'work_reassigned',(string)$item['status'],(string)$item['status'],(string)$item['priority'],work_management_require_note($note),['from_user_id'=>$before,'to_user_id'=>$targetUserId]);return$item;
}
function work_management_cancel_item(int$itemId,string$note):array{work_management_require('administer');$item=work_management_find_item($itemId);if(!$item)throw new RuntimeException('Work item not found.');if(in_array((string)$item['status'],['completed','cancelled'],true))throw new RuntimeException('Closed work cannot be cancelled again.');return work_management_transition($item,'cancelled','work_cancelled',$note);}
function work_management_policy_for_priority(string$priority):?array{foreach(work_management_escalation_policies()as$policy)if(($policy['status']??'')==='active'&&(string)$policy['priority']===$priority)return$policy;return null;}
function work_management_target_escalation_level(array$item,array$policy):int
{
    if(empty($item['due_at'])||strtotime((string)$item['due_at'])>=time())return 0;$minutes=(int)floor((time()-strtotime((string)$item['due_at']))/60);if($minutes>=(int)$policy['level3_minutes'])return 3;if($minutes>=(int)$policy['level2_minutes'])return 2;if($minutes>=(int)$policy['level1_minutes'])return 1;return 0;
}
function work_management_escalation_exists(string$key):bool{foreach(work_management_escalation_events()as$event)if(hash_equals((string)$event['idempotency_key'],$key))return true;return false;}
function work_management_escalate_item(int$itemId,string$note,?int$forcedLevel=null):array
{
    work_management_require('assign');$item=work_management_find_item($itemId);if(!$item)throw new RuntimeException('Work item not found.');if(in_array((string)$item['status'],['completed','cancelled'],true))throw new RuntimeException('Closed work cannot be escalated.');$policy=work_management_policy_for_priority((string)$item['priority']);if(!$policy)throw new RuntimeException('No active escalation policy is configured for this priority.');$target=$forcedLevel??max((int)$item['escalation_level']+1,work_management_target_escalation_level($item,$policy));$target=max(1,min(3,$target));if($target<=(int)$item['escalation_level'])return$item;$key=hash('sha256','work|'.$itemId.'|level|'.$target);if(work_management_escalation_exists($key))return$item;$from=(int)$item['escalation_level'];$action=['notify_roles'=>[],'reason'=>'sla_escalation'];if($target>=1)$action['notify_roles'][]=(string)$item['assigned_role_code'];if($target>=2)$action['notify_roles'][]=(string)$policy['backup_role_code'];if($target>=3)$action['notify_roles'][]=(string)$policy['executive_role_code'];$action['notify_roles']=array_values(array_unique(array_filter($action['notify_roles'])));
    if($target>=2){foreach(work_management_users_for_role((string)$policy['backup_role_code'],(int)$item['entity_id'],(string)$item['required_permission'])as$backup)if(!in_array((int)$backup['id'],array_filter([(int)($item['reviewer_id']??0),(int)($item['approver_id']??0)]),true)){$item['assigned_user_id']=(int)$backup['id'];break;}}
