    $item['escalation_level']=$target;$item['last_activity_at']=date('Y-m-d H:i:s');$item=work_management_save_item($item);work_management_save_escalation_event(['id'=>null,'work_item_id'=>$itemId,'policy_id'=>$policy['id'],'from_level'=>$from,'to_level'=>$target,'triggered_at'=>date('Y-m-d H:i:s'),'action_json'=>json_encode($action,JSON_UNESCAPED_SLASHES),'idempotency_key'=>$key,'created_by'=>(int)current_user()['id']]);work_management_add_event($itemId,'work_escalated',(string)$item['status'],(string)$item['status'],(string)$item['priority'],work_management_require_note($note),['from_level'=>$from,'to_level'=>$target,'actions'=>$action]);return$item;
}
function work_management_run_escalation_scan():array
{
    work_management_require('assign');$escalated=0;$unchanged=0;$errors=[];foreach(work_management_items()as$item){if(in_array((string)$item['status'],['completed','cancelled'],true))continue;$policy=work_management_policy_for_priority((string)$item['priority']);if(!$policy)continue;$target=work_management_target_escalation_level($item,$policy);if($target<=(int)$item['escalation_level']){$unchanged++;continue;}try{work_management_escalate_item((int)$item['id'],'Scheduled SLA scan escalated overdue work under policy '.$policy['policy_code'].'.',$target);$escalated++;}catch(Throwable$exception){$errors[]=$exception->getMessage();}}return['escalated'=>$escalated,'unchanged'=>$unchanged,'errors'=>array_values(array_unique($errors))];
}
